from .memory import MemoryStore
from .models import ExperimentResult
from .ollama_client import suggest_hypothesis
from .research import run_synthetic_experiment

DEFAULT_INSTRUCTIONS = [
    "Never treat backtest results as proof of future profitability.",
    "Never execute arbitrary code generated by an AI model; use the allowlisted strategy specification format.",
    "Use demo trading only for autonomous execution; live orders require a separate explicit command, confirmation, and hard risk gates.",
    "Never bypass deterministic risk controls or change safety limits autonomously.",
    "Keep a record of every experiment, including failures and rejected candidates.",
    "Do not claim calibrated win probabilities unless independently measured and calibrated.",
    "Prefer NO TRADE when data is stale, incomplete, contradictory, or a candidate fails validation."
]

class AutonomousLearningAgent:
    def __init__(self, memory: MemoryStore | None = None) -> None:
        self.memory = memory or MemoryStore()
        if not self.memory.get_instructions():
            for instruction in DEFAULT_INSTRUCTIONS: self.memory.add_instruction(instruction)

    def plan(self, objective: str) -> dict:
        history=self.memory.recent_results(limit=5)
        lessons=[item.get("lesson","") for item in history]
        hypothesis=suggest_hypothesis(objective,lessons)
        if not hypothesis:
            hypothesis=("A simple rule may behave differently across market regimes; test it on a chronologically held-out segment."
                        if history else "A candidate trading rule should be tested on data not used to define its parameters.")
        return {"objective":objective,"hypothesis":hypothesis,"steps":["Review safety instructions and prior lessons","Run a bounded research experiment","Calculate performance and drawdown","Apply preliminary numeric checks","Persist result and lesson"],"prior_experiments":len(history),"tool_permissions":["local_research","local_sqlite_memory","allowlisted_strategy_lab"]}

    def run(self, objective: str) -> tuple[dict, ExperimentResult]:
        if not objective.strip(): raise ValueError("Objective cannot be empty")
        plan=self.plan(objective.strip()); result=run_synthetic_experiment(objective.strip(),plan["hypothesis"]); self.memory.save_result(result)
        return plan,result
